def solve(a: str, b: str) -> int:
    n, m = len(a), len(b)
    # initialize previous row
    prev = list(range(m + 1))
    for i in range(1, n + 1):
        cur = [i] + [0] * m
        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                cur[j] = prev[j - 1]
            else:
                cur[j] = 1 + min(prev[j - 1], cur[j - 1], prev[j])
        prev = cur
    return prev[m]

